((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
globalThis.KENGURU_GRADES_7_8 = [{"year":2016,"id":"2016-7-8","grades":[7,8],"label":"7–8 классы","tasksUrl":"assets/kenguru/kenguru_2016_class_7-8.pdf","answersUrl":"assets/kenguru/kenguru_2016_answers.pdf","solutionUrl":null,"answerLetters":"АБВГД","cards":[{"number":1,"title":"Карточка с кенгуру","question":"Карточку, изображенную справа, перевернули сначала через нижний край, а потом — через правый край. Что получилось?","options":[{"image":"assets/grades-7-8/2016/task-01-answer-1.svg","description":"Кенгуру стоит вертикально, хвост справа"},{"image":"assets/grades-7-8/2016/task-01-answer-2.svg","description":"Кенгуру лежит головой вправо, хвост внизу"},{"image":"assets/grades-7-8/2016/task-01-answer-3.svg","description":"Кенгуру лежит головой влево, хвост внизу"},{"image":"assets/grades-7-8/2016/task-01-answer-4.svg","description":"Кенгуру перевёрнут головой вниз, хвост слева"},{"image":"assets/grades-7-8/2016/task-01-answer-5.svg","description":"Кенгуру перевёрнут головой вниз, хвост справа"}],"condition":{"src":"assets/grades-7-8/2016/task-01.svg","width":154,"height":158,"alt":"Карточка с кенгуру и стрелки двух сгибов, сначала через нижнюю, затем через правую сторону"},"answer":4,"points":3,"review":[{"title":"Решение","text":"Два переворота меняют ориентацию карточки так же, как поворот на 180° в плоскости. Верх становится низом, а левая сторона — правой."},{"title":"Ответ","text":"Голова оказывается внизу, а хвост, который направлен влево на исходной карточке, направлен вправо. Это рисунок Д."}]},{"number":2,"title":"Цифры под буквами","question":"Когда Вася зашифровал цифры буквами, оказалось, что 73489 = КЕНГА. Какое из следующих «чисел» наибольшее?","options":[{"text":"КНАГЕ"},{"text":"АГКНЕ"},{"text":"АГЕНК"},{"text":"ГНАЕК"},{"text":"АНГЕК"}],"condition":null,"answer":1,"points":3,"review":[{"title":"Решение","text":"Из равенства получаем К = 7, Е = 3, Н = 4, Г = 8, А = 9. Наибольший вариант должен начинаться с А."},{"title":"Решение","text":"Среди трёх вариантов с А сравниваем вторую букву. Г больше Н, поэтому остаются АГКНЕ и АГЕНК."},{"title":"Ответ","text":"На третьем месте К = 7 больше Е = 3. Значит, наибольшее число — АГКНЕ."}]},{"number":3,"title":"Внешние углы","question":"Чему равно α + β?","options":[{"text":"180°"},{"text":"240°"},{"text":"270°"},{"text":"300°"},{"text":"360°"}],"condition":{"src":"assets/grades-7-8/2016/task-03.svg","width":194,"height":70,"alt":"Треугольник с углом 120° внизу и отмеченными внешними углами α и β наверху"},"answer":3,"points":3,"review":[{"title":"Решение","text":"Два внутренних угла при верхних вершинах треугольника в сумме дают 180° − 120° = 60°."},{"title":"Ответ","text":"Каждый из углов α и β дополняет один из этих внутренних углов до 180°. Поэтому α + β = 360° − 60° = 300°."}]},{"number":4,"title":"Две веревочки","question":"Веревочку длины 1 и веревочку длины 2 разрезали на несколько частей каждую. Все части оказались равными по длине. Сколько могло получиться частей?","options":[{"text":"2014"},{"text":"2015"},{"text":"2016"},{"text":"2017"},{"text":"2018"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"Из второй верёвочки получается вдвое больше частей, чем из первой. Если из первой получилось n частей, то всего их 3n."},{"title":"Ответ","text":"Из вариантов только 2016 делится на 3. Можно разрезать верёвочки на 672 и 1344 равные части соответственно."}]},{"number":5,"title":"Полмиллиона","question":"Чему не равно 500 000?","options":[{"text":"половине миллиона"},{"text":"пяти тысячам сотен"},{"text":"пятидесяти тысячам десятков"},{"text":"половине тысячи тысяч"},{"text":"пяти тысячам тысяч"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Половина миллиона и половина тысячи тысяч дают по 500 000. Столько же дают 5000 × 100 и 50 000 × 10."},{"title":"Ответ","text":"Пять тысяч тысяч — это 5000 × 1000 = 5 000 000. Этот вариант отличается."}]},{"number":6,"title":"Площадь закраски","question":"Чему равна площадь закрашенной области, если ABCD — квадрат со стороной 10?","options":[{"text":"25"},{"text":"40"},{"text":"50"},{"text":"60"},{"text":"75"}],"condition":{"src":"assets/grades-7-8/2016/task-06.svg","width":124,"height":100,"alt":"В квадрате ABCD проведены диагонали и вписана окружность. Внутри окружности закрашены левая и правая доли, а вне её — верхние и нижние углы квадрата."},"answer":2,"points":3,"review":[{"title":"Решение","text":"Повернём рисунок на 90° вокруг центра квадрата. Окружность и диагонали совместятся с собой, а закрашенные области перейдут в незакрашенные."},{"title":"Ответ","text":"Площади этих областей равны. Закрашена половина площади квадрата, то есть 10 × 10 ÷ 2 = 50."}]},{"number":7,"title":"Квадраты и кубы","question":"Из чисел, квадраты которых двузначны, выбрали наибольшее, а из чисел, кубы которых трехзначны, выбрали наименьшее. Чему равна сумма выбранных чисел?","options":[{"text":"19"},{"text":"17"},{"text":"14"},{"text":"13"},{"text":"10"}],"condition":null,"answer":2,"points":3,"review":[{"title":"Решение","text":"В задаче рассматриваются натуральные числа. Наибольшее из них с двузначным квадратом — 9, потому что 9² = 81, а 10² = 100."},{"title":"Решение","text":"Наименьшее натуральное число с трёхзначным кубом — 5, потому что 4³ = 64, а 5³ = 125."},{"title":"Ответ","text":"Сумма равна 9 + 5 = 14."}]},{"number":8,"title":"Точки на плоскости","question":"На координатной плоскости четыре из пяти точек А–Д являются вершинами квадрата. Какая точка лишняя?","options":[{"text":"(1; 2)"},{"text":"(2; 3)"},{"text":"(2; 1)"},{"text":"(3; 2)"},{"text":"(2; 2)"}],"condition":null,"answer":4,"points":3,"review":[{"title":"Решение","text":"Точки (1; 2) и (3; 2) образуют горизонтальную диагональ длины 2, а (2; 1) и (2; 3) — вертикальную диагональ той же длины."},{"title":"Ответ","text":"Диагонали перпендикулярны и делятся точкой (2; 2) пополам. Четыре конца диагоналей — вершины квадрата, а точка (2; 2) — его центр."}]},{"number":9,"title":"Интересные годы","question":"Назовем год интересным, если в его записи одна из цифр вдвое больше суммы всех остальных. Например, 2016-й год — интересный (6 = 2 · (2 + 0 + 1)). Какова сумма цифр следующего интересного года?","options":[{"text":"3"},{"text":"6"},{"text":"9"},{"text":"12"},{"text":"15"}],"condition":null,"answer":3,"points":3,"review":[{"title":"Решение","text":"В 2017–2019 годах самая большая цифра больше 6, а удвоенная сумма остальных равна 6. В 2020–2022 годах ни одна цифра не подходит."},{"title":"Ответ","text":"В 2023–2027 годах удвоенная сумма остальных равна 2 × (2 + 0 + 2) = 8. Подходит 2028 год. Сумма цифр равна 12."}]},{"number":10,"title":"Лешины часы","question":"У Леши часы спешат на 7 минут, а он думает, что они отстают на 8 минут. Леша посмотрел на свои часы и решил, что сейчас полдень. Который сейчас час?","options":[{"text":"11:45"},{"text":"11:59"},{"text":"12:00"},{"text":"12:01"},{"text":"12:15"}],"condition":null,"answer":0,"points":3,"review":[{"title":"Решение","text":"Лёша прибавил 8 минут к тому, что показывали часы. Если он получил 12:00, часы показывали 11:52."},{"title":"Ответ","text":"На самом деле показание на 7 минут больше правильного времени. Сейчас 11:52 − 0:07 = 11:45."}]},{"number":11,"title":"В школьной библиотеке","question":"Ученики 7а класса посещают школьную библиотеку. В понедельник в нее пришло 5 учеников, во вторник — 6, в среду — 4, в четверг — 8, в пятницу — 7. Никто из учеников не был в библиотеке два дня подряд. Какое наименьшее количество учеников может быть в 7а классе?","options":[{"text":"12"},{"text":"15"},{"text":"18"},{"text":"25"},{"text":"30"}],"condition":null,"answer":1,"points":4,"review":[{"title":"Решение","text":"В четверг и пятницу приходили разные ученики. Значит, в классе не меньше 8 + 7 = 15 человек."},{"title":"Ответ","text":"Разделим 15 учеников на группы из 8 и 7. В понедельник, среду и пятницу придут ученики из группы семерых, а во вторник и четверг — из группы восьмерых. Все числа укладываются в такое расписание."}]},{"number":12,"title":"Наклоны прямых","question":"Три прямые a, b и c на рисунке имеют угловые коэффициенты A, B и C соответственно. Какое неравенство верно?","options":[{"text":"A > B > C"},{"text":"B > C > A"},{"text":"C > A > B"},{"text":"A > C > B"},{"text":"C > B > A"}],"condition":{"src":"assets/grades-7-8/2016/task-12.svg","width":194,"height":126,"alt":"Графики прямых a, b и c на осях координат. a убывает, b и c возрастают."},"answer":4,"points":4,"review":[{"title":"Решение","text":"При движении слева направо прямая a опускается, а b и c поднимаются. Поэтому A отрицателен, а B и C положительны."},{"title":"Ответ","text":"При одинаковом шаге вправо подъём вдоль c больше, чем вдоль b. Следовательно, C > B > A."}]},{"number":13,"title":"Слова для числа","question":"Жан-Кристоф продолжает изучать русский язык. Он ищет числа, словесная запись которых состоит ровно из четырех слов: СЕМЬ, СЕМЬДЕСЯТ, СЕМЬСОТ, ТЫСЯЧ. Например, таково число 7770 — СЕМЬ ТЫСЯЧ СЕМЬСОТ СЕМЬДЕСЯТ. Сколько всего таких чисел?","options":[{"text":"4"},{"text":"5"},{"text":"6"},{"text":"7"},{"text":"8"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Каждое из трёх числительных может стоять перед словом ТЫСЯЧ или после него. В каждой группе порядок однозначен: сотни, десятки, единицы."},{"title":"Ответ","text":"Получается 2³ = 8 распределений. Убираем одно, в котором перед словом ТЫСЯЧ пусто. Остаётся 7 чисел."}]},{"number":14,"title":"Сгибы квадратного листа","question":"У квадратного листа бумаги 10 × 10 сначала загнули справа полоску шириной 1, потом сверху полоску высотой 1, потом снова справа, потом снова сверху, и так далее (см. рисунок), пока не получился квадрат 4 × 4. После этого правый верхний квадратик 1 × 1 проткнули шилом. Сколько получится дырок, если развернуть этот лист?","options":[{"text":"51"},{"text":"49"},{"text":"40"},{"text":"36"},{"text":"25"}],"condition":{"src":"assets/grades-7-8/2016/task-14.svg","width":204,"height":106,"alt":"Сетка до и после сгибов. Показаны размеры 10 × 10, 9 × 9 и 4 × 4, точка прокола в верхней правой клетке."},"answer":1,"points":4,"review":[{"title":"Решение","text":"Ширина сократилась на 6. Каждый сгиб справа переносил накопленные слои на новую крайнюю полосу и добавлял к ней ещё одну исходную полоску."},{"title":"Решение","text":"У правого края лежат слои из 7 разных столбцов. Аналогично у верхнего края лежат слои из 7 разных строк."},{"title":"Ответ","text":"Прокол проходит через пересечения этих строк и столбцов, поэтому после разворачивания получится 7 × 7 = 49 дырок."}]},{"number":15,"title":"Сдача Винни-Пуха","question":"Винни-Пух купил в магазине четыре одинаковых горшочка с медом и заплатил несколько монет по одному фунту. Ему дали сдачу: по одной монете достоинством 50, 20, 10, 5, 2 и 1 пенсов (в одном фунте 100 пенсов). Пятачок заметил, что Винни-Пуху дали ровно одну лишнюю монету. Какую?","options":[{"text":"1 пенс"},{"text":"2 пенса"},{"text":"5 пенсов"},{"text":"20 пенсов"},{"text":"50 пенсов"}],"condition":null,"answer":3,"points":4,"review":[{"title":"Решение","text":"Сумма оплаты в пенсах кратна 100, а значит, и 4. Цена четырёх горшочков тоже кратна 4, поэтому правильная сдача должна делиться на 4."},{"title":"Ответ","text":"Выданная сдача равна 88 пенсам и уже делится на 4. Значит, лишняя монета тоже должна иметь достоинство, кратное 4. Подходит только 20 пенсов."}]},{"number":16,"title":"Произведение x, y и z","question":"Числа x, y и z таковы, что x²yz³ = 7¹¹ и xy² = 7⁷. Чему равно xyz?","options":[{"text":"7⁴"},{"text":"7⁵"},{"text":"7⁶"},{"text":"7⁷"},{"text":"7¹⁵"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Перемножим данные равенства. В левой части степень каждого числа станет равна 3, и получится (xyz)³."},{"title":"Ответ","text":"В правой части 7¹¹ × 7⁷ = 7¹⁸. Извлекаем кубический корень и получаем xyz = 7⁶."}]},{"number":17,"title":"Пары за партами","question":"В классе 20 учеников. Они сели за парты по двое так, что ровно треть мальчиков сидят с девочками, и ровно половина девочек сидят с мальчиками. Сколько мальчиков в классе?","options":[{"text":"6"},{"text":"9"},{"text":"12"},{"text":"15"},{"text":"18"}],"condition":null,"answer":2,"points":4,"review":[{"title":"Решение","text":"Пусть смешанных пар k. В каждой такой паре по одному мальчику и одной девочке."},{"title":"Решение","text":"Поскольку k составляет треть мальчиков и половину девочек, всего мальчиков 3k, а девочек 2k."},{"title":"Ответ","text":"Из 5k = 20 получаем k = 4. Мальчиков 3 × 4 = 12."}]},{"number":18,"title":"Числа в треугольниках","question":"Алиса хочет вписать шесть чисел в кружки на рисунке так, чтобы суммы чисел в вершинах всех пяти треугольников были равными. Какое наибольшее количество различных чисел может оказаться на рисунке?","options":[{"text":"1"},{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"}],"condition":{"src":"assets/grades-7-8/2016/task-18.svg","width":136,"height":142,"alt":"Пять кружков на вершинах пятиугольника и один в центре. Центр соединён со всеми вершинами."},"answer":1,"points":4,"review":[{"title":"Решение","text":"Два соседних треугольника имеют две общие вершины. Чтобы суммы были равны, числа на их оставшихся вершинах должны совпадать."},{"title":"Решение","text":"Так по кругу равны числа на каждой второй внешней вершине. Внешних вершин пять, поэтому этот обход посещает все пять, и в них стоит одно число."},{"title":"Ответ","text":"В центральном кружке можно поставить другое число. Максимум — два."}]},{"number":19,"title":"Свечки для братьев","question":"Бим, Бом и Бам — братья-тройняшки, а их братья-двойняшки Труляля и Траляля ровно на три года их младше. На день рождения всех пяти братьев мама приготовила им большой торт со свечками. Число свечек было равно сумме возрастов всех пяти братьев. Сколько свечек могло быть на этом торте?","options":[{"text":"34"},{"text":"53"},{"text":"76"},{"text":"88"},{"text":"92"}],"condition":null,"answer":0,"points":4,"review":[{"title":"Решение","text":"Если двойняшкам по n лет, то тройняшкам по n + 3. Всего нужно 2n + 3(n + 3) = 5n + 9 свечек."},{"title":"Ответ","text":"Среди вариантов только 34 даёт остаток 4 при делении на 5. При n = 5 получаем 5 + 5 + 8 + 8 + 8 = 34."}]},{"number":20,"title":"Склеенные кубики","question":"Семь стандартных игральных кубиков склеили вместе, как показано на рисунке. Приклеенные друг к другу грани содержат одинаковое число точек, а остальные грани закрашены. Сколько всего точек было на закрашенных гранях?","options":[{"text":"24"},{"text":"90"},{"text":"95"},{"text":"105"},{"text":"126"}],"condition":{"src":"assets/grades-7-8/2016/task-20.svg","width":132,"height":128,"alt":"Один кубик в центре и шесть кубиков, приклеенных к его граням"},"answer":3,"points":4,"review":[{"title":"Решение","text":"У каждого кубика 1 + 2 + 3 + 4 + 5 + 6 = 21 точка на всех гранях, у семи кубиков — 147."},{"title":"Решение","text":"Все шесть граней центрального кубика приклеены к другим кубикам. Скрытые грани внешних кубиков повторяют числа на центральном, поэтому скрыто 2 × 21 = 42 точки."},{"title":"Ответ","text":"На закрашенных гранях остаётся 147 − 42 = 105 точек."}]},{"number":21,"title":"Касающиеся окружности","question":"На рисунке изображены окружности с центрами в точках A, B, C, D и E. Отрезками соединены центры касающихся окружностей. Известно, что AB = 16, BC = 14, CD = 17, DE = 13 и AE = 14. В какой точке находится центр окружности наибольшего радиуса?","options":[{"text":"A"},{"text":"B"},{"text":"C"},{"text":"D"},{"text":"E"}],"condition":{"src":"assets/grades-7-8/2016/task-21.svg","width":184,"height":174,"alt":"Пять окружностей с центрами A, B, C, D и E касаются по циклу. Соседние центры соединены отрезками."},"answer":0,"points":5,"review":[{"title":"Решение","text":"Расстояние между центрами двух внешне касающихся окружностей равно сумме их радиусов. Обозначим радиус при A через a."},{"title":"Решение","text":"Тогда радиусы при B, C, D и E последовательно равны 16 − a, a − 2, 19 − a и a − 6."},{"title":"Ответ","text":"Из суммы радиусов при A и E получаем 2a − 6 = 14, откуда a = 10. Остальные радиусы равны 6, 8, 9 и 4, так что наибольший радиус у окружности с центром A."}]},{"number":22,"title":"Черные клетки","question":"В квадрате 3 × 3 некоторые клетки белые, а остальные — черные. Известно, что не во всех столбцах не все клетки черные. Тогда обязательно","options":[{"text":"в каждом столбце есть черная клетка"},{"text":"все клетки черные"},{"text":"есть столбец из белых клеток"},{"text":"все клетки белые"},{"text":"есть столбец из черных клеток"}],"condition":null,"answer":4,"points":5,"review":[{"title":"Решение","text":"Фраза «не во всех столбцах» означает, что есть столбец, для которого утверждение «не все клетки чёрные» неверно."},{"title":"Ответ","text":"В этом столбце все клетки чёрные. Остальные столбцы условие дополнительно не ограничивает."}]},{"number":23,"title":"Числа Васи","question":"Вася выбрал несколько различных натуральных чисел. Произведение двух самых маленьких из них равно 16, а произведение двух самых больших равно 225. Чему равна сумма всех Васиных чисел?","options":[{"text":"243"},{"text":"44"},{"text":"42"},{"text":"38"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Два наименьших числа образуют пару (1, 16) или (2, 8). Для двух наибольших возможны пары (1, 225), (3, 75), (5, 45) и (9, 25)."},{"title":"Решение","text":"Меньшее число в паре наибольших не может быть меньше второго числа в паре наименьших. По этому условию подходят только пары (2, 8) и (9, 25)."},{"title":"Ответ","text":"Между 8 и 9 нет целых чисел. Всего получаем 2 + 8 + 9 + 25 = 44."}]},{"number":24,"title":"Монеты Васи и Пети","question":"Если Вася даст Пете 6 монет, то у них станет поровну монет, а если Петя даст Васе 9 монет, то у Васи монет станет в k раз больше, чем у Пети. При каком наибольшем k это возможно?","options":[{"text":"20"},{"text":"25"},{"text":"30"},{"text":"31"},{"text":"37"}],"condition":null,"answer":3,"points":5,"review":[{"title":"Решение","text":"Если после передачи Васей 6 монет их станет поровну, значит, первоначально у Васи на 12 монет больше."},{"title":"Решение","text":"После передачи Петей 9 монет разность увеличится ещё на 18 и станет равна 30. Пусть у Пети останется n монет, тогда отношение равно (n + 30) ÷ n = 1 + 30 ÷ n."},{"title":"Ответ","text":"Это отношение наибольшее при n = 1. Петя мог иметь 10 монет, а Вася 22. После передачи у них будет 1 и 31 монета соответственно, поэтому k = 31."}]},{"number":25,"title":"Шесть точек на прямой","question":"Шесть точек A, B, C, D, E и F расположены на прямой в некотором порядке так, что AB = 1, BC = 3, CD = 4, DE = 5, EF = 10, FA = 11. Какие две точки крайние?","options":[{"text":"B и F"},{"text":"A и F"},{"text":"B и C"},{"text":"A и E"},{"text":"невозможно определить"}],"condition":null,"answer":0,"points":5,"review":[{"title":"Решение","text":"Возьмём A за 0 и направим ось от A к F. Тогда F имеет координату 11."},{"title":"Решение","text":"Если бы все пять шагов от A к B, C, D, E и F шли в положительном направлении, их сумма равнялась бы 1 + 3 + 4 + 5 + 10 = 23. Каждый отрицательный шаг уменьшает итог на удвоенную длину, поэтому длины отрицательных шагов в сумме дают (23 − 11) ÷ 2 = 6."},{"title":"Ответ","text":"Из данных длин 6 можно набрать только как 1 + 5. Координаты B, C, D и E равны −1, 2, 6 и 1. Крайними являются B и F."}]},{"number":26,"title":"Шестая грань куба","question":"Большой куб 3 × 3 × 3 сложен из 27 одинаковых маленьких кубиков, 15 из которых закрашены, а 12 — белые. Пять граней большого куба изображены на рисунке справа. Как выглядит его шестая грань?","options":[{"image":"assets/grades-7-8/2016/task-26-answer-1.svg","description":"Клетки, закрашенные по строкам: две крайние, две крайние, правая"},{"image":"assets/grades-7-8/2016/task-26-answer-2.svg","description":"Клетки, закрашенные по строкам: две крайние, правая с центральной, две крайние"},{"image":"assets/grades-7-8/2016/task-26-answer-3.svg","description":"Клетки, закрашенные по строкам: две крайние, центральная, две крайние"},{"image":"assets/grades-7-8/2016/task-26-answer-4.svg","description":"Клетки, закрашенные по строкам: две правые, ни одной, две левые"},{"image":"assets/grades-7-8/2016/task-26-answer-5.svg","description":"Клетки, закрашенные по строкам: две крайние, все три, правая"}],"condition":{"src":"assets/grades-7-8/2016/task-26.svg","width":216,"height":132,"alt":"Пять квадратных граней 3 × 3 с разными белыми и закрашенными клетками"},"answer":0,"points":5,"review":[{"title":"Решение","text":"Угловой кубик виден на трёх гранях, поэтому число закрашенных углов на всех гранях кратно 3. На пяти показанных гранях их 15. Только варианты А и Д добавляют по три угла. Значит, закрашенных угловых кубиков 18 ÷ 3 = 6."},{"title":"Решение","text":"Кубик в середине ребра виден на двух гранях. На пяти известных гранях закрашено 8 середин рёбер, а каждый из двух оставшихся вариантов добавляет ещё 2. Всего закрашено 10 ÷ 2 = 5 таких кубиков."},{"title":"Ответ","text":"На известных гранях четыре закрашенных центра, поэтому уже учтены 6 + 5 + 4 = 15 кубиков. Центр скрытой грани белый, как на рисунке А."}]},{"number":27,"title":"Пассажиры в вагонах","question":"В поезде 5 вагонов, в каждом вагоне есть хоть один пассажир. Будем говорить, что два пассажира едут рядом, если они едут в одном вагоне или в двух соседних. Известно, что рядом с каждым пассажиром едут еще либо 5, либо 10 пассажиров. Сколько всего пассажиров в поезде?","options":[{"text":"20"},{"text":"17"},{"text":"15"},{"text":"13"},{"text":"невозможно определить"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Для пассажира первого вагона в первых двух вагонах всего 6 или 11 человек с ним самим. Для пассажира второго вагона в первых трёх вагонах тоже 6 или 11 человек, причём эта сумма строго больше первой."},{"title":"Решение","text":"Значит, в первых двух вагонах 6 человек, а в первых трёх — 11. По такому же рассуждению в двух последних вагонах 6 человек."},{"title":"Ответ","text":"Складываем количества в первых трёх и последних двух вагонах и получаем 11 + 6 = 17."}]},{"number":28,"title":"Обгоны на дорожке","question":"По круговой дорожке в одном направлении двигаются Женя пешком и малыш Федя на велосипеде. Скорость Феди на 75 % больше скорости Жени, и поэтому время от времени он ее обгоняет. В скольких разных точках дорожки будут происходить обгоны?","options":[{"text":"2"},{"text":"3"},{"text":"4"},{"text":"5"},{"text":"6"}],"condition":null,"answer":1,"points":5,"review":[{"title":"Решение","text":"Между двумя обгонами Федя выигрывает ровно один круг. Разница скоростей составляет 3/4 скорости Жени."},{"title":"Решение","text":"За это время Женя проходит 4/3 круга. Поэтому очередная точка обгона сдвигается на треть круга вперёд."},{"title":"Ответ","text":"Через три таких сдвига обе позиции повторяются. Получаются три разные точки."}]},{"number":29,"title":"Цифры числа и квадрата","question":"Лена возвела натуральное число N в квадрат и сложила количество цифр в числе N с количеством цифр в числе N². Какой результат у нее не мог получиться?","options":[{"text":"98"},{"text":"99"},{"text":"100"},{"text":"101"},{"text":"102"}],"condition":null,"answer":2,"points":5,"review":[{"title":"Решение","text":"Если у N ровно d цифр, то у N² бывает 2d − 1 или 2d цифр. Первый случай достигается на N = 10ᵈ⁻¹, второй — на N = 9 × 10ᵈ⁻¹."},{"title":"Решение","text":"Значит, сумма равна 3d − 1 или 3d. Числа 98 и 99 получаются при d = 33, а 101 и 102 — при d = 34."},{"title":"Ответ","text":"Число 100 при делении на 3 даёт остаток 1. Такая сумма невозможна."}]},{"number":30,"title":"Угол у точки M","question":"На продолжении стороны AC треугольника ABC отмечена точка M (см. рисунок). Известно, что CM = 2 AC, ∠CBA = 15° и ∠CAB = 45°. Найдите ∠AMB.","options":[{"text":"60°"},{"text":"65°"},{"text":"70°"},{"text":"72°"},{"text":"75°"}],"condition":{"src":"assets/grades-7-8/2016/task-30.svg","width":206,"height":176,"alt":"Треугольник ABM, на стороне AM лежит C. Отмечены угол CBA 15°, угол CAB 45° и искомый угол AMB."},"answer":4,"points":5,"review":[{"title":"Решение","text":"Из углов треугольника ABC получаем ∠ACB = 120°, поэтому ∠BCM = 60°."},{"title":"Решение","text":"Опустим из B перпендикуляр BH на прямую AM и примем AC за 1. Из угла A = 45° следует AH = BH, а из угла BCM = 60° следует BH = √3 · CH."},{"title":"Ответ","text":"Положив AH = t, получаем t = √3(t − 1), откуда t = (3 + √3)/2. Тогда тангенс ∠AMB равен BH ÷ HM = t ÷ (3 − t) = 2 + √3, то есть углу 75°."}]}]}];
'use strict';

(() => {
  const archive = globalThis.KENGURU_ARCHIVE ??= {};
  const visual = globalThis.KenguruVisual;
  const cyrillicAnswers = 'АБВГД';

  function circleComparison(step, frame) {
    const outline = '#54877e';
    const fill = ['#347d75', '#43998c', '#60a99d', '#2e807c'];
    const ink = '#172e34';
    const radius = 43;
    const quarter = 'M0 0H43A43 43 0 0 0 0 -43Z';
    if (step === 1) {
      const opacity = .25 + .75 * visual.reveal(frame);
      return visual.svg(`<rect x="225" y="20" width="190" height="190" rx="3" fill="#f1f6ee" stroke="${outline}" stroke-width="2"/>
        <path d="M320 115H415A95 95 0 0 0 320 20Z" fill="${fill[0]}" opacity="${opacity}"/>
        <path d="M320 123V130M415 123V130M320 126H415" fill="none" stroke="${ink}" stroke-width="2"/>
        <text x="367.5" y="154" fill="${ink}" font-size="17" text-anchor="middle">радиус</text>`,
      'Радиус четверти круга равен половине стороны квадрата', '0 0 640 230', 'worked-scene');
    }
    if (step !== 2) return null;

    const far = radius;
    const offsets = [
      [[-far, far], [-far, -far], [far, -far], [far, far]],
      [[0, 0], [0, 0], [0, 0], [0, 0]],
      [[-far, 0], [-far, 0], [far, 0], [far, 0]],
      [[0, far], [-far, -far], [far, -far], [0, far]],
    ];
    const groups = offsets.map((pieces, index) => {
      const x = index % 2 === 0 ? 222 : 418;
      const y = index < 2 ? 95 : 254;
      const start = index * .38;
      const turn = index === 1 ? 0 : 180 * visual.reveal((frame - start) * 2.5);
      const remaining = 1 - visual.reveal((frame - start - 1.2) * 1.15);
      const paths = pieces.map(([dx, dy], piece) =>
        `<path d="${quarter}" fill="${fill[piece]}" stroke="#fffefa"
          stroke-width=".6" transform="translate(${x + dx * remaining} ${y + dy * remaining}) rotate(${90 * piece + turn})"/>`
      ).join('');
      return `<rect x="${x - radius}" y="${y - radius}" width="${radius * 2}" height="${radius * 2}"
        fill="#f1f6ee" stroke="${outline}" stroke-width="1.6"/>${paths}
        <text x="${x - 96}" y="${y + 6}" fill="${ink}" font-size="20" text-anchor="middle">${cyrillicAnswers[index]}</text>`;
    });
    return visual.svg(groups.join(''), 'Четыре четверти каждого рисунка складываются в целый круг',
      '102 0 432 348', 'worked-scene');
  }

  function shadeCells(step, frame) {
    if (step !== 2) return null;
    const alreadyShaded = [2, 4, 7, 9];
    const newlyShaded = [0, 1];
    const cells = Array.from({length: 12}, (_, index) => {
      const x = 90 + index % 4 * 42;
      const y = 20 + Math.floor(index / 4) * 42;
      const change = newlyShaded.indexOf(index);
      const opacity = alreadyShaded.includes(index) ? 1 : change < 0 ? 0 : visual.reveal(frame * 2 - change * .65);
      return `<rect x="${x}" y="${y}" width="42" height="42" fill="#fff"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="#202020" opacity="${opacity}"/>
        <rect x="${x}" y="${y}" width="42" height="42" fill="none" stroke="#202020" stroke-width="1.2"/>`;
    });
    return visual.svg(cells.join(''), 'В двух белых клетках верхней строки появляется чёрная заливка',
      '65 6 218 154', 'worked-scene');
  }

  const editions = [...(globalThis.KENGURU_GRADES_7_8 ?? []), ...(globalThis.KENGURU_JUNIOR_SENIOR ?? [])];
  for (const edition of editions) {
    const answerLetters = [...(edition.answerLetters ?? cyrillicAnswers)];
    const {id, year, label, grades, tasksUrl, answersUrl, solutionUrl, cards} = edition;
    const lessons = [];
    const scenes = [];

    for (const {number, title, question, questionNote, options, condition, answer, points, review, keyNote} of cards) {
      const hasReview = review.length > 0;
      const choiceImages = options.map(option => option.image);
      const choices = options.map(option => option.text ?? '');
      const answerLetter = answerLetters[answer];
      const steps = [['Условие', 'Условие задачи', '']];
      for (const [index, stage] of review.entries()) {
        const final = index === review.length - 1;
        steps.push([final ? 'Ответ' : 'Шаг ' + (index + 1), stage.title, stage.text]);
      }
      if (!hasReview) {
        steps.push(['Ответ', 'Проверка по ключу', keyNote ?? (answerLetter ? 'Правильный вариант — ' + answerLetter + '.' : 'Сверь решение с ответом в PDF.')]);
      }

      lessons.push({
        number, title, short: title, question, questionNote, points, answer, choices, choiceImages,
        choiceLayout: {condition, options}, conditionImage: condition?.src, conditionAlt: condition?.alt,
        hideIntroText: true, paperEdition: !hasReview, showCompletedStep: hasReview,
        officialValueKey: answer === null,
        steps,
      });

      const keyedAnswer = visual.answerScene({letter: answerLetter, value: choices[answer]});
      scenes.push((step, frame) => {
        if (!step) return '';
        if (!hasReview) return keyedAnswer;
        const stage = review[step - 1];
        const animation = id === '2026-7-8' && number === 1 ? circleComparison(step, frame)
          : id === '2017-2' && number === 6 ? shadeCells(step, frame) : null;
        return animation ?? (visual.workedScene(stage, frame)
          || (step === review.length ? keyedAnswer : ''));
      });
    }
    archive[id] = {id, year, label, grades, answerLetters, sources: {tasksUrl, answersUrl, solutionUrl}, lessons, scenes};
  }
})();

register((globalThis.KENGURU_ARCHIVE["2016-7-8"] ?? [].concat(globalThis.KENGURU_ARCHIVE[2016] ?? []).find(edition => edition.id === "2016-7-8")), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
